/** For every plan on the sheet, in the order added, a DRAFT claim of the plan's amount for each plan
 *  date (the start, then every N days; or the day of the month in every month) up to its end and the sheet's today that it has not made yet,
 *  dated that day with an empty note, by the claim form's rules: a date the form refuses is skipped,
 *  and tried again the next time. A plan naming a descendant sheet makes its claims for the person of
 *  the same name there (none when there is none), by that sheet's rules and in that sheet's audit. Each claim is saved and audited as an added claim. A viewer makes none. */
public class GeneratePlans {
    public void generate(@PathVariable("sheetId") String sheetId, @Val Actor actor, Plans plans, People people,
            Sheets sheets, ClosedPeriods closedPeriods, Claims claims, Settings settings, Holidays holidays,
            ClaimLog log, Audit audit, Out<GeneratePlansResult> result) {
        if (settings.role(sheetId, actor.user()) == net.officefloor.hq.app.settings.Role.VIEWER) {
            result.set(new GeneratePlansResult(0)); // a viewer changes nothing
            return;
        }
        LocalDate today = sheets.today(sheetId);
        RecordClaimAdded record = new RecordClaimAdded();
        Map<Long, Person> persons = new HashMap<>();
        int made = 0;
        for (Plan plan : plans.onSheet(sheetId)) {
            Person person = persons.computeIfAbsent(plan.personId(), id -> people.find(sheetId, id));
            if (person == null) continue;
            if (plan.targetSheet() != null) {
                person = people.named(plan.targetSheet(), person.getName()); // none there: it makes none
                if (person == null) continue;
            }
            LocalDate last = plan.end().isBefore(today) ? plan.end() : today;
            for (LocalDate date : plan.dates(last)) {
                if (plans.made(plan.id(), date)) continue;
                ClaimValues values = new ClaimValues(plan.amount(), date, "", null, actor.user(), null, null);
                Claim claim;
                try {
                    claim = ClaimForm.built(values, person, sheets, closedPeriods, claims, settings, holidays);
                } catch (Exception refused) {
                    continue;
                }
                claims.save(claim);
                plans.markMade(sheetId, plan.id(), date);
                record.record(values, person, claim, log, audit);
                made++;
            }
        }
        result.set(new GeneratePlansResult(made));
    }
}
package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The plans of each sheet, in the order added, the plan dates each has made its claim for, its pauses
 *  and its changes of amount. */
@Repository
public class Plans {

    private final JdbcTemplate jdbc;

    public Plans(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every plan on the sheet, in the order added, with how many claims it has made so far and its pauses. */
    public List<Plan> onSheet(String sheetId) {
        Map<Long, List<PlanChange>> changes = new HashMap<>();
        jdbc.query("SELECT plan_id, changed_on, amount FROM plan_change WHERE sheet_id = ? ORDER BY id",
                (org.springframework.jdbc.core.RowCallbackHandler) rs -> changes
                        .computeIfAbsent(rs.getLong(1), k -> new ArrayList<>())
                        .add(new PlanChange(rs.getDate(2).toLocalDate(), rs.getBigDecimal(3).setScale(2))),
                sheetId);
        Map<Long, List<PlanPause>> pauses = new HashMap<>();
        jdbc.query("SELECT plan_id, paused_on, resumed_on FROM plan_pause WHERE sheet_id = ? ORDER BY id",
                (org.springframework.jdbc.core.RowCallbackHandler) rs -> pauses
                        .computeIfAbsent(rs.getLong(1), k -> new ArrayList<>())
                        .add(new PlanPause(rs.getDate(2).toLocalDate(),
                                rs.getDate(3) == null ? null : rs.getDate(3).toLocalDate())),
                sheetId);
        return jdbc.query("SELECT p.id, p.sheet_id, p.person_id, p.amount, p.start_date, p.every_days, p.month_day, p.end_date, p.target_sheet, "
                + "(SELECT COUNT(*) FROM plan_claim c WHERE c.plan_id = p.id) "
                + "FROM plan p WHERE p.sheet_id = ? ORDER BY p.id",
                (rs, i) -> new Plan(rs.getLong(1), rs.getString(2), rs.getLong(3), rs.getBigDecimal(4).setScale(2),
                        rs.getDate(5).toLocalDate(), rs.getObject(6, Integer.class), rs.getObject(7, Integer.class),
                        rs.getDate(8).toLocalDate(), rs.getInt(10),
                        pauses.getOrDefault(rs.getLong(1), List.of()),
                        changes.getOrDefault(rs.getLong(1), List.of()), rs.getString(9)),
                sheetId);
    }

    /** Adds the plan; answers its id. */
    public long add(String sheetId, long personId, BigDecimal amount, LocalDate start, Integer every, Integer day,
            LocalDate end, String targetSheet) {
        jdbc.update("INSERT INTO plan (sheet_id, person_id, amount, start_date, every_days, month_day, end_date, target_sheet) "
                + "VALUES (?, ?, ?, ?, ?, ?, ?, ?)", sheetId, personId, amount, Date.valueOf(start), every, day,
                Date.valueOf(end), targetSheet);
        return jdbc.queryForObject("SELECT MAX(id) FROM plan WHERE sheet_id = ? AND person_id = ?", Long.class,
                sheetId, personId);
    }

    /** Whether the plan has made its claim for that plan date. */
    public boolean made(long planId, LocalDate date) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM plan_claim WHERE plan_id = ? AND on_date = ?",
                Integer.class, planId, Date.valueOf(date));
        return n != null && n > 0;
    }

    /** Notes the plan has made its claim for that plan date. */
    public void markMade(String sheetId, long planId, LocalDate date) {
        jdbc.update("INSERT INTO plan_claim (sheet_id, plan_id, on_date) VALUES (?, ?, ?)", sheetId, planId,
                Date.valueOf(date));
    }

    /** The plan on the sheet with that id, or null when there is none. */
    public Plan find(String sheetId, long planId) {
        return onSheet(sheetId).stream().filter(p -> p.id() == planId).findFirst().orElse(null);
    }

    /** Opens a pause of the plan from that day. */
    public void pause(String sheetId, long planId, LocalDate on) {
        jdbc.update("INSERT INTO plan_pause (sheet_id, plan_id, paused_on) VALUES (?, ?, ?)", sheetId, planId,
                Date.valueOf(on));
    }

    /** Changes the plan's amount on that day, from then on, and notes the change. */
    public void changeAmount(String sheetId, long planId, LocalDate on, BigDecimal amount) {
        jdbc.update("UPDATE plan SET amount = ? WHERE id = ?", amount, planId);
        jdbc.update("INSERT INTO plan_change (sheet_id, plan_id, changed_on, amount) VALUES (?, ?, ?, ?)", sheetId,
                planId, Date.valueOf(on), amount);
    }

    /** Ends the plan's open pause on that day. */
    public void resume(long planId, LocalDate on) {
        jdbc.update("UPDATE plan_pause SET resumed_on = ? WHERE plan_id = ? AND resumed_on IS NULL", Date.valueOf(on),
                planId);
    }
}
package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;

/** A person's plan: a claim of `amount` on the start date and every `every` days after, or (`every`
 *  null) monthly on `day` of the month, up to the end date; `generated` is how many claims it has
 *  made so far; `pauses` its pauses in the order made, a plan date in one skipped; `changes` its
 *  changes of amount, oldest first (`amount` is the latest); `targetSheet` the descendant
 *  sheet its claims are made on (for the person of the same name there), or null for its own. */
public record Plan(long id, String sheetId, long personId, BigDecimal amount, LocalDate start, Integer every,
        Integer day, LocalDate end, int generated, List<PlanPause> pauses, List<PlanChange> changes, String targetSheet) {

    /** Whether the plan is paused now: it has a pause not yet resumed. */
    public boolean paused() {
        return pauses.stream().anyMatch(p -> p.resumedOn() == null);
    }

    private boolean skipped(LocalDate date) {
        return pauses.stream().anyMatch(p -> p.skips(date));
    }

    /** The plan dates from the start up to `last`, in order: the start then every N days, or the
     *  day of the month in every month from the start's month (a day beyond the month's length on
     *  its last day), dates before the start and dates in a pause left out. */
    public List<LocalDate> dates(LocalDate last) {
        List<LocalDate> dates = new ArrayList<>();
        if (every != null) {
            for (LocalDate date = start; !date.isAfter(last); date = date.plusDays(every)) dates.add(date);
        } else {
            for (YearMonth month = YearMonth.from(start); !month.atDay(1).isAfter(last); month = month.plusMonths(1)) {
                LocalDate date = month.atDay(Math.min(day, month.lengthOfMonth()));
                if (!date.isBefore(start) && !date.isAfter(last)) dates.add(date);
            }
        }
        dates.removeIf(this::skipped);
        return dates;
    }

    /** The first `count` plan dates after `today` and on or before the end, in order. */
    public List<LocalDate> nextDates(LocalDate today, int count) {
        List<LocalDate> next = new ArrayList<>();
        for (LocalDate date : dates(end)) {
            if (next.size() == count) break;
            if (date.isAfter(today)) next.add(date);
        }
        return next;
    }
}
